style.css:
@-moz-document domain("chatgpt.com"), domain("openai.com"), domain("platform.openai.com"), domain("labs.openai.com") {
:root {
    /* Базовые цвета Dracula */
    --drac-bg-a: #282a36;          /* основной фон */
    --drac-bg-b: #44475a;          /* вторичный фон / панели */
    --drac-bg-c: #6272a4;          /* подсветки и лейблы */
    --drac-text: #ffffff;          /* основной текст */
    --drac-text-dim: #aaaaaa;      /* вторичный текст */
    --drac-text-disabled: #717171; /* отключённый текст */
    --drac-accent: #bd93f9;        /* фиолет — акцент */
    --drac-accent-strong: #ff5555; /* красный — CTA */
    --drac-green: #50fa7b;         /* подтверждения */
    --drac-outline: rgba(255,255,255,0.3);
    --drac-overlay: rgba(0,0,0,0.8);

    /* Токены для сайтов OpenAI */
    --oa-surface-0: var(--drac-bg-a);
    --oa-surface-1: var(--drac-bg-b);
    --oa-surface-2: #35384a;
    --oa-border: rgba(255,255,255,0.08);
    --oa-ring: var(--drac-accent);
    --oa-link: var(--drac-accent);
    --oa-link-hover: #c9aafc;
    --oa-danger: var(--drac-accent-strong);
    --oa-success: var(--drac-green);
    --oa-text: var(--drac-text);
    --oa-text-dim: var(--drac-text-dim);
    --oa-code-bg: #1f2230;
  }

  /* Универсальные фоны/текст */
  html, body {
    background: var(--oa-surface-0) !important;
    color: var(--oa-text) !important;
  }

  /* Скроллбары (поддерживается в Firefox и частично в других) */
  html *:not(code):not(pre) {
    scrollbar-color: var(--drac-accent) var(--oa-surface-1);
  }

  /* Ссылки */
  a, .link, .prose a {
    color: var(--oa-link) !important;
  }
  a:hover, .link:hover, .prose a:hover {
    color: var(--oa-link-hover) !important;
  }

  /* Кнопки — общий вид */
  button, [role="button"], .btn, [class^="Button_button__"], .ui-button {
    background: var(--oa-surface-1) !important;
    color: var(--oa-text) !important;
    border: 1px solid var(--oa-border) !important;
    box-shadow: none !important;
  }
  button:hover, [role="button"]:hover, .btn:hover, [class^="Button_button__"]:hover, .ui-button:hover {
    background: var(--oa-surface-2) !important;
    border-color: var(--oa-ring) !important;
  }

  /* Кнопки действия */
  .primary, .btn-primary, button[type="submit"], .ui-button.primary {
    background: var(--drac-accent) !important;
    color: #030303 !important;
    border-color: rgba(255,255,255,0.2) !important;
  }
  .primary:hover, .btn-primary:hover, button[type="submit"]:hover, .ui-button.primary:hover {
    filter: brightness(1.1);
  }

  /* Инпуты и селекты */
  input, textarea, select, .input, .ui-input, [role="textbox"] {
    background: var(--oa-surface-1) !important;
    color: var(--oa-text) !important;
    border: 1px solid var(--oa-border) !important;
  }
  input::placeholder, textarea::placeholder {
    color: var(--oa-text-dim) !important;
  }
  input:focus, textarea:focus, select:focus, .ui-input:focus {
    outline: 2px solid var(--oa-ring) !important;
    outline-offset: 0 !important;
    border-color: var(--oa-ring) !important;
    box-shadow: 0 0 0 3px rgba(189,147,249,0.25) !important;
  }

  /* Формы/ввод */
  form textarea {
    background: var(--oa-surface-1) !important;
  }

  /* Карточки, панели, модалки */
  .card, .panel, .prose blockquote, .shadow, .rounded-lg, .modal, .Dialog, .Sheet, .Popover, .dropdown-menu {
    background: var(--oa-surface-1) !important;
    color: var(--oa-text) !important;
    border: 1px solid var(--oa-border) !important;
  }

  /* Разделители */
  hr, .divider, .border-t, .border-b, .border, .ProseMirror hr {
    border-color: var(--oa-border) !important;
    color: var(--oa-border) !important;
  }

  /* Код, markdown, сообщения чата */
  pre, code, .cm-editor, .markdown, .prose pre, .prose code {
    background: var(--oa-code-bg) !important;
    color: var(--oa-text) !important;
    border: 1px solid var(--oa-border) !important;
  }
  .prose code {
    padding: .1rem .3rem;
    border-radius: .4rem;
  }
  pre code { border: none !important; }

  /* ChatGPT — лейаут */
  /* Левая панель чатов / Projects */
  [data-testid*="sidebar"], nav[aria-label*="Sidebar"], aside {
    background: var(--oa-surface-1) !important;
    border-right: 1px solid var(--oa-border) !important;
  }

  /* Список чатов */
  [data-testid*="conversation"] li,
  [class*="conversation"] li,
  [class*="thread"] li {
    background: transparent !important;
  }
  [data-testid*="conversation"] li:hover,
  [class*="conversation"] li:hover,
  [class*="thread"] li:hover {
    background: rgba(255,255,255,0.05) !important;
  }

  /* Верхняя панель */
  header, [data-testid*="header"], .top-bar, .sticky.top-0 {
    background: var(--oa-surface-1) !important;
    border-bottom: 1px solid var(--oa-border) !important;
  }

  /* Сообщения ассистента/пользователя */
  .markdown.prose, [data-testid*="assistant"], [data-testid*="user"], .chat-message {
    background: var(--oa-surface-0) !important;
    color: var(--oa-text) !important;
  }
  .chat-message:hover { background: rgba(255,255,255,0.03) !important; }

  /* Табы и чипы */
  .tab, .tabs [role="tab"], .chip, .badge {
    background: var(--oa-surface-2) !important;
    color: var(--oa-text) !important;
    border: 1px solid var(--oa-border) !important;
  }
  .tab[aria-selected="true"], .tabs [role="tab"][aria-selected="true"], .chip.active {
    border-color: var(--oa-ring) !important;
    box-shadow: inset 0 0 0 2px rgba(189,147,249,0.25) !important;
  }

  /* Страницы openai.com (маркетинг) */
  .hero, .section, .container, .article {
    background: var(--oa-surface-0) !important;
    color: var(--oa-text) !important;
  }
  .hero .cta, .button.cta {
    background: var(--drac-accent) !important;
    color: #030303 !important;
  }

  /* Таблицы */
  table {
    background: var(--oa-surface-1) !important;
    border: 1px solid var(--oa-border) !important;
    border-collapse: collapse;
  }
  thead, th { background: #3b3f55 !important; }
  tr { border-bottom: 1px solid var(--oa-border) !important; }

  /* Уведомления */
  .alert-success { background: rgba(80,250,123,0.15) !important; color: var(--oa-text) !important; }
  .alert-error { background: rgba(255,85,85,0.15) !important; color: var(--oa-text) !important; }

  /* Фокус/выделение */
  *:focus { outline: 2px solid var(--oa-ring) !important; outline-offset: 2px !important; }
  ::selection { background: rgba(189,147,249,0.35); color: #fff; }

  /* Мелкие правки контрастности */
  .text-muted, .muted, .subtle, .text-secondary { color: var(--oa-text-dim) !important; }
  .disabled, [aria-disabled="true"], :disabled { color: var(--drac-text-disabled) !important; }

  /* Экраны загрузки/оверлеи (без ::backdrop) */
  .backdrop, .overlay { background: var(--drac-overlay) !important; }

  /* Снижаем агрессивные тени */
  .shadow-lg, .ring-1 { box-shadow: none !important; }
}
